func:
if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/court-email-scan';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {'Content-Type':'application/json','X-API-Key':apiKey,'X-Api-Key':apiKey};
msg.payload = { since_hours: 24 };
msg.method = 'POST';
node.status({fill:'blue',shape:'dot',text:'Scanning court email…'});
return msg;

const r = (msg.payload && msg.payload.result) || msg.payload || {};
const by = r.by_type || {};
const processed = r.processed || 0;
if (processed === 0 && !r.error) {
  node.status({fill:'green',shape:'ring',text:'No new court mail'});
  return null;
}
msg.headers = {
  Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
  'Content-Type': 'application/json; charset=utf-8'
};
const fort = by.forfeiture || 0;
msg.payload = {
  channel: fort > 0 ? '#alerts' : (global.get('SLACK_CHANNEL_BONDS') || '#bonds'),
  text: [
    '⚖️ *Court Email Scanner*',
    `Processed: ${processed} · Calendar: ${r.calendar_events_created||0} · Emails: ${r.emails_sent||0} · BB: ${r.messages_sent||0}`,
    `Types — Court: ${by.courtDate||0} · Forfeiture: ${fort} · Discharge: ${by.discharge||0} · Other: ${by.unknown||0}`,
    r.error ? ('⚠️ ' + r.error) : ''
  ].filter(Boolean).join('\n')
};
node.status({fill: fort>0?'red':'green', shape:'dot', text: processed + ' processed'});
return msg;

if (global.get('SYSTEM_SHUTDOWN')) return null;
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
const surety = msg.surety || msg.topic || 'OSI';
msg.url = base + '/api/automation/bond-report';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {'Content-Type':'application/json','X-API-Key':apiKey,'X-Api-Key':apiKey};
msg.payload = { surety: String(surety).toUpperCase(), include_discharges: true, store: true };
msg.method = 'POST';
msg._reportSurety = String(surety).toUpperCase();
node.status({fill:'blue',shape:'dot',text:'Building '+msg._reportSurety+' report…'});
return msg;

const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
const headers = {'Content-Type':'application/json','X-API-Key':apiKey,'X-Api-Key':apiKey};
return [
  { ...msg, url: base+'/api/automation/bond-report', method:'POST', headers, payload:{surety:'OSI',include_discharges:true,store:true}, _reportSurety:'OSI' },
  { ...msg, url: base+'/api/automation/bond-report', method:'POST', headers, payload:{surety:'PALMETTO',include_discharges:true,store:true}, _reportSurety:'PALMETTO' }
];

const p = msg.payload || {};
if (!p.ok && !p.filename) {
  node.status({fill:'red',shape:'dot',text:'Report failed'});
  node.error(p.error || 'bond report failed', msg);
  return null;
}
msg.headers = {
  Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
  'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
  channel: global.get('SLACK_CHANNEL_BONDS') || '#bonds',
  text: `📑 *Official ${p.surety || msg._reportSurety || ''} Bond Report* ready\nFile: \`${p.filename}\` · ${p.size_bytes||0} bytes · Active scanned: ${p.active_rows_scanned||0} · Discharges: ${p.discharges||0}`
};
// Keep base64 off Slack text — stored in leads generated_reports
node.status({fill:'green',shape:'dot',text:(p.surety||'')+' report OK'});
return msg;

if (global.get('SYSTEM_SHUTDOWN')) return null;
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/discharge-report';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {'Content-Type':'application/json','X-API-Key':apiKey,'X-Api-Key':apiKey};
msg.payload = { surety: 'ALL', days_back: 90 };
msg.method = 'POST';
return msg;

const p = msg.payload || {};
if (!p.ok) return null;
msg.headers = {
  Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
  'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
  channel: global.get('SLACK_CHANNEL_BONDS') || '#bonds',
  text: `🟢 *Official Discharge Report*\nFile: \`${p.filename}\` · Rows: ${p.discharge_rows||0} · Window: ${p.days_back||90}d`
};
return msg;

msg.headers = {
  Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
  'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = { channel: '#alerts', text: '🚨 *Court Email & Reports error*: ' + ((msg.error&&msg.error.message)||'unknown') };
return msg;
